// (тикет про размеры скриншотов на всех устройствах). Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { fileName, openLanding, productImages, scrollAndWaitLoaded } from './landing-helpers';

test.describe('Landing — скриншоты системы (#99cf43b7)', () => {
  test('Product screenshots fit the screen width without horizontal scroll #99cf43b7 @prod-safe', async ({ page }) => {
    await openLanding(page);
    const imgs = productImages(page);
    const count = await imgs.count();

    for (let i = 0; i < count; i++) {
      const img = imgs.nth(i);
      await scrollAndWaitLoaded(img);
      const box = await img.evaluate((e) => {
        const r = e.getBoundingClientRect();
        return { src: (e as HTMLImageElement).src, left: r.left, right: r.right, vw: window.innerWidth };
      });
      const name = fileName(box.src);
      expect(box.left, `${name}: левый край`).toBeGreaterThanOrEqual(0);
      expect(box.right, `${name}: правый край`).toBeLessThanOrEqual(box.vw);
    }

    // Горизонтальной прокрутки нет
    const { sw, vw } = await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, vw: window.innerWidth }));
    expect(sw, 'горизонтальная прокрутка').toBeLessThanOrEqual(vw);
  });
});
